i wish somebody would feature request rust_enum library to be included in the standard library, its a very useful library specially if you're using match case in your code.

enum Message {
    Quit,
    Move{x: i32, y: i32},
    Write(String),
    ChangeColor(u8,u8,u8)
}

fn process_message(msg: Message) {
    match msg {
        Message::Quit => println!("Quit Application"),
        Message::Move { x, y } => println!("Move to position: {} {}", x, y),
        Message::Write(text) => println!("Message: {}", text),
        Message::ChangeColor(r,g ,b ) => println!("Change Color to RGB({}, {}, {})", r, g, b)
    }
}

fn main() {
    process_message(Message::Quit);
    process_message(Message::Move { x: 10, y: 20 });
    process_message(Message::Write("hello there!".to_string()));
    process_message(Message::ChangeColor(255, 0, 255));
}

-----------------------------
python version
----------------------------

from rust_enum import Case, enum, Option # type: ignore

@enum
class Message:
    Quit = Case()
    Move = Case(x=int, y=int)
    Write = Case(text = str)
    ChangeColor = Case(r=int, g=int, b=int)


def process_message(msg: Message):
    match msg:
        case Message.Quit: print(f"Quit Appllication")

        case Message.Move(x=x,y=y): print(f"Move to position: ({x}, {y})")

        case Message.Write(text=t):  print(f"Writing: {t}")

        case Message.ChangeColor(r=r, g=g, b=b): print(f"Changing to color: ({r}, {g}, {b})")

        case _: print("Unknown Message")


def main() -> None:
    process_message(Message.Quit)
    process_message(Message.Move(x=10, y=20))
    process_message(Message.Write("hello there!"))
    process_message(Message.ChangeColor(r=255, g=0, b=255))

if __name__=="__main__":
    main()


--------------------------------
Rust version using impl method
--------------------------------

enum Message {
    Quit,
    Move {x: i32, y: i32},
    Write(String),
    ChangeColor(u8, u8, u8)
}

impl Message {
    fn process_message(&self) {
        match self {
            Message::Quit => println!("Quiting Appllication"),
            Message::Move {x, y} => println!("Moving to position: ({}, {})", x,y),
            Message::Write(text) => println!("Message: {}", text),
            Message::ChangeColor(r,g, b) => println!("change color to ({}, {}, {})", r,g,b)

        }
    }
}

fn main() {
    Message::Quit.process_message();
    Message::Move { x: 10, y: 20 }.process_message();
    Message::Write(String::from("Hello There! impl")).process_message();
    Message::ChangeColor(255, 0, 255).process_message();
}

----------------------------------
python version using methods
---------------------------------
from rust_enum import Case, enum, Option # type: ignore

@enum
class Message:
    Quit = Case()
    Move = Case(x=int, y=int)
    Write = Case(text = str)
    ChangeColor = Case(r=int, g=int, b=int)


    def process_message(self):
        match self:
            case Message.Quit(): print(f"Quit Application")

            case Message.Move(x=x,y=y): print(f"Move to position: ({x}, {y})")

            case Message.Write(text=t):  print(f"Writing: {t}")

            case Message.ChangeColor(r=r, g=g, b=b): print(f"Changing to color: ({r}, {g}, {b})")

            case _: print("Unknown Message")


def main():
    Message.Quit().process_message()
    Message.Move(x=10, y=20).process_message()
    Message.Write("Hello There!").process_message()
    Message.ChangeColor(255, 0, 255).process_message()
    

if __name__=="__main__":
    main()

